// web/build/optimize-svg.mjs
//
// Reads the committed converter output in assets/ and writes optimized copies into
// dist/assets/. It deliberately does NOT rewrite assets/ in place: those 587 files are
// generated by scripts/web-svg-converter.main.kts and drift-checked by token_drift.yml,
// so mutating them would leave the working tree dirty and let a developer commit
// optimized bytes that nothing regenerates.
//
// scripts/web-svg-converter.main.kts decides what an icon *is* — its currentColor
// behaviour, its filename, the typed manifest. This step only shrinks bytes.
import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { optimize } from 'svgo'
import { iconConfig, artworkConfig } from '../svgo.config.mjs'

const __dirname = dirname(fileURLToPath(import.meta.url))
const ROOT = join(__dirname, '..')

const FAMILIES = [
  { dir: 'assets/icons', config: iconConfig },
  { dir: 'assets/flags', config: artworkConfig },
  { dir: 'assets/brand-logos', config: artworkConfig },
]

for (const { dir, config } of FAMILIES) {
  const sourceDir = join(ROOT, dir)
  const targetDir = join(ROOT, 'dist', dir)
  await mkdir(targetDir, { recursive: true })

  // Sorted so the per-family summary is stable across machines.
  const files = (await readdir(sourceDir)).filter((f) => f.endsWith('.svg')).sort()
  let before = 0
  let after = 0
  for (const file of files) {
    const path = join(sourceDir, file)
    const input = await readFile(path, 'utf8')
    const { data } = optimize(input, { path, ...config })
    before += input.length
    after += data.length
    await writeFile(join(targetDir, file), data)
  }
  const saved = before === 0 ? 0 : Math.round((1 - after / before) * 100)
  console.log(`✓ dist/${dir}: ${files.length} files, ${saved}% smaller`)
}
